<section x-show="page==='tasks'" class="page-enter"><div class="page-heading"><div><div class="eyebrow">تمرکز روی قدم بعدی</div><h1>تسک‌های من</h1><p>کارهایی که به شما سپرده شده یا در انجام آن‌ها همراه هستید.</p></div><button class="button primary" @click="openTask()"><span x-html="$icon('Plus')"></span>افزودن تسک</button></div><div class="tasks-toolbar"><div class="segmented"><button :class="{'selected':taskFilter==='active'}" @click="taskFilter='active'">تسک‌های باز <span x-text="fa(myTasks.filter(t=>!t.completed_at).length)"></span></button><button :class="{'selected':taskFilter==='done'}" @click="taskFilter='done'">تکمیل‌شده‌ها</button><button :class="{'selected':taskFilter==='all'}" @click="taskFilter='all'">همه</button></div><div class="button-row"><select x-model="selectedProject" class="compact-select" aria-label="انتخاب پروژه"><option value="all">همه پروژه‌ها</option><template x-for="p in projects" :key="p.id"><option :value="p.id" x-text="p.name"></option></template></select><div class="view-switch"><button class="icon-btn" :class="{'selected':view==='board'}" @click="view='board'" aria-label="نمای برد" x-html="$icon('LayoutGrid')"></button><button class="icon-btn" :class="{'selected':view==='list'}" @click="view='list'" aria-label="نمای فهرست" x-html="$icon('List')"></button></div></div></div><template x-for="p in boardProjects" :key="p.id"><section class="task-project-section"><div class="section-heading"><h2><i class="project-dot" :style="`background:${p.color}`"></i><span x-text="p.name"></span></h2><button class="text-button" @click="go('projects',p.id)">مشاهده پروژه <span x-html="$icon('ArrowUpLeft')"></span></button></div><div class="board" :class="{'list-view':view==='list'}"><template x-for="(s,i) in myStages(p)" :key="s.id"><section class="board-column"><div class="stage-column-head"><div><span class="stage-dot" :style="`background:${stageColor(i)}`"></span><h3 x-text="s.title"></h3><span class="count-badge" x-text="fa(stageTasks(s.id,true).length)"></span></div><div x-data="{open:false}" class="stage-menu" @click.outside="open=false"><button class="icon-btn" @click="open=!open" :aria-label="'گزینه‌های '+s.title" x-html="$icon('MoreHorizontal')"></button><div class="dropdown-menu" x-show="open" x-transition.opacity.scale.95.duration.150ms><button @click="openStage(s,user,p);open=false">تغییر نام</button><button @click="openStage(s,user,p);open=false">تنظیم تاریخ</button><button class="danger-text" @click="deleteStage(s,'member',user);open=false">حذف ستون</button></div></div></div><div class="stage-meta"><span x-text="s.product_stage?.title||'بدون مرحله محصول'"></span></div><div class="column-tasks"><template x-for="t in stageTasks(s.id,true)" :key="t.id">@include('partials.task-card')</template><div class="column-empty" x-show="!stageTasks(s.id,true).length"><span x-html="$icon('CheckCheck')"></span><span>تسکی برای شما در این مرحله نیست.</span></div></div><button class="add-column-task" x-show="canWrite(p)" @click="openTask(null,s,p)"><span x-html="$icon('Plus')"></span>افزودن تسک</button></section></template><section class="board-column add-column-card" x-show="canWrite(p)"><button x-show="inlineColumn?.kind!=='member'||inlineColumn?.project_id!==p.id" @click="startInlineColumn('member',p)">＋ افزودن ستون</button><form x-show="inlineColumn?.kind==='member'&&inlineColumn?.project_id===p.id" @submit.prevent="saveInlineColumn('member',p)" @keydown.escape.prevent="cancelInlineColumn()"><select x-model.number="inlineColumnForm.product_stage_id" required><option value="">مرحله محصول مادر</option><template x-for="ps in p.stages" :key="ps.id"><option :value="ps.id" x-text="ps.title"></option></template></select><input data-inline-column-input x-model="inlineColumnForm.title" placeholder="نام ستون" maxlength="120"><div class="button-row"><button class="button primary small-button" type="submit">افزودن</button><button class="text-button" type="button" @click="cancelInlineColumn()">لغو</button></div></form></section></div></section></template><div class="empty-state" x-show="!boardProjects.length"><span x-html="$icon('CheckCircle2')"></span><h2>همه چیز مرتب است</h2><p>تسک بازی ندارید. وقت یک شروع تازه است!</p><button class="button primary" @click="openTask()">افزودن تسک</button></div></section>
